{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Perindopril, an ACE inhibitor prodrug with a bicyclic ring and a carboxylic acid metabolite, has an absolute oral bioavailability of about 75% in humans, supporting high F for the query's acidic bicyclic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Nicainoprol, a drug with an aromatic ether and alcohol, shows a mean oral bioavailability of 69.4% in eight human subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bornaprolol, a beta-blocker with an aryloxypropanolamine, shows absolute oral bioavailability of 46% at a 120 mg dose in normal volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Nipradilol, a beta-blocker with an aromatic ether and nitrooxy group, shows F of 32% in younger subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pethidine, a phenylpiperidine ester, has an absolute oral bioavailability of 52% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Warfarin, an acidic drug with an aromatic ring, has nearly complete oral bioavailability, supporting high F for an acidic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Nonylphenol, a lipophilic alkylphenol, has an oral bioavailability of 20% in humans, meeting the F>=20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Propranolol, a high-clearance beta-blocker, has a mean absolute oral bioavailability of 27.2% in fasting subjects, supporting high F despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Perindoprilat, the polar diacid active metabolite of perindopril, has an oral bioavailability of 19% ± 7% in young healthy subjects, below the 20% threshold, providing affirmative low-F evidence for an acidic, polar bicyclic molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high oral bioavailability (F >= 20%) because the large majority of highly transferable experimental analogues (perindopril, nicainoprol, bornaprolol, nipradilol, pethidine, warfarin, nonylphenol, propranolol) show F at or above 20%, while the only low-F analogue (perindoprilat) is a more polar diacid with limited structural overlap.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule; prediction relies on transferable analogues.",
    "The TP-434 record (C34) is associated with a SMILES mismatch (myristic acid vs eravacycline), so it was not used as a primary anchor.",
    "Perindoprilat low F is from a polar diacid; query has one carboxylic acid and a more lipophilic core, so transferability is uncertain.",
    "Propranolol shows high interindividual variability around the threshold, but its mean F is above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

